class Solution {
public:
    int largestComponentSize(vector<int>& nums) {
        int maxVal = 0;
        for (int x : nums) if (x > maxVal) maxVal = x;
        if (maxVal < 2) return nums.empty() ? 0 : 1;

        vector<int> spf(maxVal + 1);
        for (int i = 0; i <= maxVal; i++) spf[i] = i;
        for (int i = 2; (long long)i * i <= maxVal; i++) {
            if (spf[i] == i) {
                for (int j = i * i; j <= maxVal; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }

        vector<int> parent(maxVal + 1);
        vector<int> rnk(maxVal + 1, 0);
        for (int i = 0; i <= maxVal; i++) parent[i] = i;

        auto find = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };
        auto unite = [&](int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return;
            if (rnk[ra] < rnk[rb]) { int t = ra; ra = rb; rb = t; }
            parent[rb] = ra;
            if (rnk[ra] == rnk[rb]) rnk[ra]++;
        };

        for (int x : nums) {
            int v = x;
            while (v > 1) {
                int p = spf[v];
                unite(x, p);
                while (v % p == 0) v /= p;
            }
        }

        unordered_map<int,int> cnt;
        int ans = 0;
        for (int x : nums) {
            int r = find(x);
            cnt[r]++;
            if (cnt[r] > ans) ans = cnt[r];
        }
        return ans;
    }
};
